DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.get_public_host(text)'::regprocedure) INTO d; d:=replace(d,'IF p.id IS NULL OR NOT p.host_public THEN RETURN NULL; END IF;','IF p.id IS NULL OR NOT p.host_public OR EXISTS(SELECT 1 FROM public.user_suspensions s WHERE s.user_id=p.id) THEN RETURN NULL; END IF;'); EXECUTE d; SELECT pg_get_functiondef('public.get_public_event(uuid)'::regprocedure) INTO d; d:=replace(d, 'SELECT jsonb_build_object(''name'', p.full_name, ''avatar_url'', p.avatar_url, ''verified'', public.is_verified_coach(p.id)) INTO _host FROM public.profiles p WHERE p.id = e.host_id;', 'SELECT jsonb_build_object(''name'', h->>''name'', ''avatar_url'', h->>''avatar_url'', ''slug'', h->>''slug'', ''verified'', public.is_verified_coach(e.host_id)) INTO _host FROM (SELECT public.get_public_host(p.slug) AS h FROM public.profiles p WHERE p.id=e.host_id) x WHERE h IS NOT NULL;'); EXECUTE d; END $$;